bun -e '
import { readdirSync, readFileSync } from "fs";
import { join } from "path";
import { parseDispatchEmail } from "./src/providers/email.ts";
const expected = {
  "alibaba.txt": {"store":"alibaba","storeOrderNumber":"123456789012345","trackingNumber":"ALB9988776655","carrier":"Alibaba Logistics"},
  "amazon.txt": {"store":"amazon","storeOrderNumber":"112-4455667-1234567","trackingNumber":"1Z999AA10123456784","carrier":"UPS"},
  "ebay.txt": {"store":"ebay","storeOrderNumber":"12-34567-89012","trackingNumber":"794612345678","carrier":"FedEx"},
  "homecenter.txt": {"store":"homecenter","storeOrderNumber":"458221","trackingNumber":"HC4582210099","carrier":"Homecenter"},
  "mercadolibre.txt": {"store":"mercadolibre","storeOrderNumber":"2000003847563","trackingNumber":"999001234567","carrier":"Servientrega"},
};
let bad = 0;
for (const f of readdirSync("fixtures/correos").sort()) {
  const got = parseDispatchEmail(readFileSync(join("fixtures/correos", f), "utf8"));
  const ok = JSON.stringify(got) === JSON.stringify(expected[f]);
  if (!ok) bad++;
  console.log(ok ? "OK  " : "FAIL", f, JSON.stringify(got));
}
process.exit(bad ? 1 : 0);
' && bun scripts/verificar.ts

